-- Table: advertisement_details
DROP TABLE IF EXISTS `advertisement_details`;
CREATE TABLE `advertisement_details` (
  `advertisement_id` bigint(20) unsigned NOT NULL,
  `pricing_model` enum('flat','cpc','cpm') DEFAULT 'flat',
  `rate` decimal(12,2) DEFAULT 0.00,
  `impressions` bigint(20) unsigned DEFAULT 0,
  `clicks` bigint(20) unsigned DEFAULT 0,
  `target_city_id` bigint(20) unsigned DEFAULT NULL,
  `target_category_id` bigint(20) unsigned DEFAULT NULL,
  `charge_amount` decimal(12,2) DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `alt_text` varchar(255) DEFAULT NULL,
  `device_target` enum('all','desktop','mobile','tablet') NOT NULL DEFAULT 'all',
  `priority` int(11) NOT NULL DEFAULT 10,
  `impression_limit` bigint(20) unsigned NOT NULL DEFAULT 0,
  `click_limit` bigint(20) unsigned NOT NULL DEFAULT 0,
  `frequency_cap` int(10) unsigned NOT NULL DEFAULT 0,
  `audience_note` varchar(500) DEFAULT NULL,
  `billing_status` enum('unpaid','paid','waived','refunded') NOT NULL DEFAULT 'unpaid',
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`advertisement_id`),
  KEY `fk_ad_details_city` (`target_city_id`),
  KEY `fk_ad_details_category` (`target_category_id`),
  KEY `idx_ad_details_device` (`device_target`),
  KEY `idx_ad_details_billing` (`billing_status`),
  KEY `fk_ad_details_approver` (`approved_by`),
  CONSTRAINT `fk_ad_details_ad` FOREIGN KEY (`advertisement_id`) REFERENCES `advertisements` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ad_details_approver` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ad_details_category` FOREIGN KEY (`target_category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ad_details_city` FOREIGN KEY (`target_city_id`) REFERENCES `cities` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: advertisements
