  `sort_order` int(11) NOT NULL DEFAULT 10,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_blog_category_status` (`status`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: blog_comments
DROP TABLE IF EXISTS `blog_comments`;
CREATE TABLE `blog_comments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `author_name` varchar(160) NOT NULL,
  `author_email` varchar(190) DEFAULT NULL,
  `comment_text` text NOT NULL,
  `status` enum('pending','approved','spam','rejected') NOT NULL DEFAULT 'pending',
  `ip_hash` varchar(128) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `moderated_at` datetime DEFAULT NULL,
  `moderated_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_blog_comment_post_status` (`post_id`,`status`,`created_at`),
  KEY `fk_blog_comment_user` (`user_id`),
  KEY `fk_blog_comment_moderator` (`moderated_by`),
  CONSTRAINT `fk_blog_comment_moderator` FOREIGN KEY (`moderated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_blog_comment_post` FOREIGN KEY (`post_id`) REFERENCES `blog_posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_blog_comment_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: blog_post_tags
DROP TABLE IF EXISTS `blog_post_tags`;
CREATE TABLE `blog_post_tags` (
  `post_id` bigint(20) unsigned NOT NULL,
  `tag_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`post_id`,`tag_id`),
  KEY `fk_blog_post_tag_tag` (`tag_id`),
  CONSTRAINT `fk_blog_post_tag_post` FOREIGN KEY (`post_id`) REFERENCES `blog_posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_blog_post_tag_tag` FOREIGN KEY (`tag_id`) REFERENCES `blog_tags` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: blog_posts
DROP TABLE IF EXISTS `blog_posts`;
CREATE TABLE `blog_posts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `author_id` bigint(20) unsigned NOT NULL,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `city_id` bigint(20) unsigned DEFAULT NULL,
  `business_id` bigint(20) unsigned DEFAULT NULL,
  `language` enum('en','ur','bilingual') NOT NULL DEFAULT 'en',
  `post_type` enum('article','video') NOT NULL DEFAULT 'article',
  `title_en` varchar(320) DEFAULT NULL,
  `title_ur` varchar(420) DEFAULT NULL,
  `slug` varchar(360) NOT NULL,
  `excerpt_en` varchar(900) DEFAULT NULL,
  `excerpt_ur` varchar(1100) DEFAULT NULL,
  `body_en` longtext DEFAULT NULL,
  `body_ur` longtext DEFAULT NULL,
  `cover_image` varchar(700) DEFAULT NULL,
  `video_url` varchar(700) DEFAULT NULL,
  `meta_title` varchar(320) DEFAULT NULL,
  `meta_description` varchar(700) DEFAULT NULL,
  `canonical_url` varchar(700) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `comments_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `status` enum('draft','scheduled','published','archived') NOT NULL DEFAULT 'draft',
  `published_at` datetime DEFAULT NULL,
  `views` bigint(20) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_blog_author_status` (`author_id`,`status`),
  KEY `idx_blog_status_date` (`status`,`published_at`),
  KEY `idx_blog_featured` (`is_featured`,`status`,`published_at`),
  KEY `idx_blog_category` (`category_id`,`status`),
  KEY `idx_blog_city` (`city_id`,`status`),
  KEY `fk_blog_business` (`business_id`),
  CONSTRAINT `fk_blog_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_blog_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_blog_category` FOREIGN KEY (`category_id`) REFERENCES `blog_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_blog_city` FOREIGN KEY (`city_id`) REFERENCES `cities` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: blog_tags
DROP TABLE IF EXISTS `blog_tags`;
CREATE TABLE `blog_tags` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
