-- Table: commerce_invoices
DROP TABLE IF EXISTS `commerce_invoices`;
CREATE TABLE `commerce_invoices` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `invoice_number` varchar(40) NOT NULL,
  `order_id` bigint(20) unsigned DEFAULT NULL,
  `payment_order_id` bigint(20) unsigned DEFAULT NULL,
  `buyer_user_id` bigint(20) unsigned DEFAULT NULL,
  `seller_user_id` bigint(20) unsigned DEFAULT NULL,
  `issue_date` date NOT NULL,
  `due_date` date DEFAULT NULL,
  `subtotal` decimal(14,2) NOT NULL DEFAULT 0.00,
