  KEY `idx_news_category_status` (`status`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: news_posts
DROP TABLE IF EXISTS `news_posts`;
CREATE TABLE `news_posts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `city_id` bigint(20) unsigned DEFAULT NULL,
  `business_id` bigint(20) unsigned DEFAULT NULL,
  `post_type` enum('article','video') NOT NULL DEFAULT 'article',
  `language` enum('en','ur','bilingual') NOT NULL DEFAULT 'bilingual',
  `title_en` varchar(300) DEFAULT NULL,
  `title_ur` varchar(400) DEFAULT NULL,
  `slug` varchar(340) NOT NULL,
  `excerpt_en` varchar(800) DEFAULT NULL,
  `excerpt_ur` varchar(1000) DEFAULT NULL,
  `body_en` longtext DEFAULT NULL,
  `body_ur` longtext DEFAULT NULL,
  `image_url` varchar(700) DEFAULT NULL,
  `video_url` varchar(700) DEFAULT NULL,
  `source_name` varchar(180) DEFAULT NULL,
  `source_url` varchar(700) DEFAULT NULL,
  `reporter_name` varchar(180) DEFAULT NULL,
  `is_breaking` tinyint(1) NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('draft','scheduled','published','archived') NOT NULL DEFAULT 'draft',
  `published_at` datetime DEFAULT NULL,
  `views` bigint(20) unsigned NOT NULL DEFAULT 0,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_news_status_date` (`status`,`published_at`),
  KEY `idx_news_type` (`post_type`,`status`),
  KEY `idx_news_language` (`language`,`status`),
  KEY `idx_news_breaking` (`is_breaking`,`status`,`published_at`),
  KEY `idx_news_featured` (`is_featured`,`status`,`published_at`),
  KEY `idx_news_category` (`category_id`,`status`),
  KEY `idx_news_city` (`city_id`,`status`),
  KEY `fk_news_business` (`business_id`),
  KEY `fk_news_creator` (`created_by`),
  CONSTRAINT `fk_news_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_news_category` FOREIGN KEY (`category_id`) REFERENCES `news_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_news_city` FOREIGN KEY (`city_id`) REFERENCES `cities` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_news_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: news_widgets
DROP TABLE IF EXISTS `news_widgets`;
CREATE TABLE `news_widgets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `widget_key` varchar(80) NOT NULL,
