-- Table: store_auction_bids
DROP TABLE IF EXISTS `store_auction_bids`;
CREATE TABLE `store_auction_bids` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `auction_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `bid_amount` decimal(14,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_store_bid_auction` (`auction_id`,`bid_amount`),
  KEY `idx_store_bid_user` (`user_id`),
  CONSTRAINT `fk_store_bid_auction` FOREIGN KEY (`auction_id`) REFERENCES `store_auctions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_store_bid_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: store_auctions
DROP TABLE IF EXISTS `store_auctions`;
CREATE TABLE `store_auctions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint(20) unsigned NOT NULL,
  `start_price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `current_price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `min_increment` decimal(14,2) NOT NULL DEFAULT 100.00,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `status` enum('scheduled','live','ended','cancelled') NOT NULL DEFAULT 'scheduled',
  `winner_user_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_id` (`product_id`),
  KEY `idx_store_auction_status` (`status`,`starts_at`,`ends_at`),
  KEY `fk_store_auction_winner` (`winner_user_id`),
  CONSTRAINT `fk_store_auction_product` FOREIGN KEY (`product_id`) REFERENCES `store_products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_store_auction_winner` FOREIGN KEY (`winner_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: store_categories
DROP TABLE IF EXISTS `store_categories`;
CREATE TABLE `store_categories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(140) NOT NULL,
  `slug` varchar(160) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 10,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: store_order_items
DROP TABLE IF EXISTS `store_order_items`;
CREATE TABLE `store_order_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) unsigned NOT NULL,
  `product_id` bigint(20) unsigned NOT NULL,
  `title` varchar(220) NOT NULL,
  `product_type` enum('new','used','digital') NOT NULL,
  `quantity` int(11) NOT NULL DEFAULT 1,
  `unit_price` decimal(14,2) NOT NULL,
  `line_total` decimal(14,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_store_order_item_order` (`order_id`),
  KEY `fk_store_order_item_product` (`product_id`),
  CONSTRAINT `fk_store_order_item_order` FOREIGN KEY (`order_id`) REFERENCES `store_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_store_order_item_product` FOREIGN KEY (`product_id`) REFERENCES `store_products` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: store_orders
DROP TABLE IF EXISTS `store_orders`;
CREATE TABLE `store_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_number` varchar(80) NOT NULL,
  `buyer_user_id` bigint(20) unsigned NOT NULL,
  `seller_user_id` bigint(20) unsigned NOT NULL,
  `auction_id` bigint(20) unsigned DEFAULT NULL,
  `subtotal` decimal(14,2) NOT NULL DEFAULT 0.00,
  `shipping_total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `grand_total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `payment_method` enum('cod','advance') NOT NULL DEFAULT 'cod',
  `payment_status` enum('unpaid','awaiting_review','paid','refunded') NOT NULL DEFAULT 'unpaid',
  `payment_order_id` bigint(20) unsigned DEFAULT NULL,
  `status` enum('pending','confirmed','processing','shipped','delivered','completed','cancelled') NOT NULL DEFAULT 'pending',
  `customer_name` varchar(160) NOT NULL,
  `customer_phone` varchar(40) NOT NULL,
  `customer_email` varchar(190) DEFAULT NULL,
  `shipping_address` varchar(500) DEFAULT NULL,
  `city_text` varchar(160) DEFAULT NULL,
  `notes` varchar(700) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_number` (`order_number`),
  UNIQUE KEY `auction_id` (`auction_id`),
  UNIQUE KEY `payment_order_id` (`payment_order_id`),
  KEY `idx_store_order_buyer` (`buyer_user_id`,`status`),
  KEY `idx_store_order_seller` (`seller_user_id`,`status`),
  CONSTRAINT `fk_store_order_auction` FOREIGN KEY (`auction_id`) REFERENCES `store_auctions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_store_order_buyer` FOREIGN KEY (`buyer_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_store_order_payment` FOREIGN KEY (`payment_order_id`) REFERENCES `payment_orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_store_order_seller` FOREIGN KEY (`seller_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: store_products
DROP TABLE IF EXISTS `store_products`;
CREATE TABLE `store_products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `seller_user_id` bigint(20) unsigned NOT NULL,
  `business_id` bigint(20) unsigned DEFAULT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `city_id` bigint(20) unsigned DEFAULT NULL,
  `product_type` enum('new','used','digital') NOT NULL DEFAULT 'new',
  `sale_mode` enum('fixed','auction') NOT NULL DEFAULT 'fixed',
  `title` varchar(220) NOT NULL,
  `slug` varchar(240) NOT NULL,
  `short_description` varchar(500) DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `image_url` varchar(700) DEFAULT NULL,
  `digital_file_path` varchar(700) DEFAULT NULL,
  `price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `compare_price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `stock` int(11) NOT NULL DEFAULT 1,
  `condition_notes` varchar(700) DEFAULT NULL,
  `shipping_charge` decimal(14,2) NOT NULL DEFAULT 0.00,
  `allow_cod` tinyint(1) NOT NULL DEFAULT 1,
  `allow_advance` tinyint(1) NOT NULL DEFAULT 1,
  `location_text` varchar(300) DEFAULT NULL,
  `status` enum('draft','pending','published','rejected','soldout','archived') NOT NULL DEFAULT 'pending',
  `featured` tinyint(1) NOT NULL DEFAULT 0,
  `views` bigint(20) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_store_product_seller` (`seller_user_id`,`status`),
  KEY `idx_store_product_type` (`product_type`,`sale_mode`,`status`),
  KEY `idx_store_product_category` (`category_id`,`status`),
  KEY `fk_store_product_business` (`business_id`),
  KEY `fk_store_product_city` (`city_id`),
  CONSTRAINT `fk_store_product_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_store_product_category` FOREIGN KEY (`category_id`) REFERENCES `store_categories` (`id`),
  CONSTRAINT `fk_store_product_city` FOREIGN KEY (`city_id`) REFERENCES `cities` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_store_product_seller` FOREIGN KEY (`seller_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: subscription_invoices
DROP TABLE IF EXISTS `subscription_invoices`;
CREATE TABLE `subscription_invoices` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `invoice_no` varchar(80) NOT NULL,
  `subscription_id` bigint(20) unsigned DEFAULT NULL,
  `business_id` bigint(20) unsigned NOT NULL,
  `plan_id` bigint(20) unsigned NOT NULL,
  `payment_order_id` bigint(20) unsigned DEFAULT NULL,
  `issue_date` date NOT NULL,
  `due_date` date NOT NULL,
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `discount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `tax` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `status` enum('unpaid','partial','paid','overdue','void','waived') NOT NULL DEFAULT 'unpaid',
  `notes` varchar(700) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoice_no` (`invoice_no`),
  UNIQUE KEY `payment_order_id` (`payment_order_id`),
  KEY `idx_sub_invoice_business` (`business_id`),
  KEY `idx_sub_invoice_status` (`status`),
  KEY `idx_sub_invoice_due` (`due_date`),
  KEY `fk_sub_invoice_subscription` (`subscription_id`),
  KEY `fk_sub_invoice_plan` (`plan_id`),
  KEY `fk_sub_invoice_creator` (`created_by`),
  CONSTRAINT `fk_sub_invoice_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`),
  CONSTRAINT `fk_sub_invoice_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_sub_invoice_order` FOREIGN KEY (`payment_order_id`) REFERENCES `payment_orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_sub_invoice_plan` FOREIGN KEY (`plan_id`) REFERENCES `subscription_plans` (`id`),
  CONSTRAINT `fk_sub_invoice_subscription` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: subscription_plan_details
DROP TABLE IF EXISTS `subscription_plan_details`;
CREATE TABLE `subscription_plan_details` (
  `plan_id` bigint(20) unsigned NOT NULL,
  `duration_days` int(10) unsigned DEFAULT 365,
  `business_limit` int(10) unsigned DEFAULT 1,
  `featured_limit` int(10) unsigned DEFAULT 0,
  `ad_credit` decimal(12,2) DEFAULT 0.00,
  `description` text DEFAULT NULL,
  `features_text` text DEFAULT NULL,
  `approval_mode` enum('auto','manual','payment') DEFAULT 'payment',
  `recommended` tinyint(1) DEFAULT 0,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`plan_id`),
  CONSTRAINT `fk_plan_details_plan` FOREIGN KEY (`plan_id`) REFERENCES `subscription_plans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: subscription_plans
DROP TABLE IF EXISTS `subscription_plans`;
CREATE TABLE `subscription_plans` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `slug` varchar(120) NOT NULL,
  `price` decimal(12,2) DEFAULT 0.00,
  `billing_period` enum('monthly','yearly','custom') DEFAULT 'yearly',
  `features_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features_json`)),
  `status` tinyint(1) DEFAULT 1,
